-- ExamGrind verified daily current-affairs desk: 11 November 2026.
-- Coverage window: substantive official releases on 10 November and late 9 November regulator material.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
$$2026-11-11-plfs-july-september-quarterly-bulletin$$, $$2026-11-11$$,
$$PLFS reports higher labour-force participation in July-September 2026$$,
$$The National Statistical Office's latest PLFS quarterly bulletin put the all-India labour-force participation rate for people aged 15 and above at 55.5%, up from 54.6% in the preceding quarter. The worker-population ratio rose to 52.7%, while rural unemployment fell to 4.3%. The estimates use the Current Weekly Status framework.$$,
$$PLFS is India's principal official source for employment and unemployment indicators. This release tests the meaning of LFPR, WPR, unemployment rate and Current Weekly Status, as well as the National Statistical Office's role under MoSPI.$$,
$$The PLFS methodology was revised from January 2025 to generate monthly and quarterly all-India indicators for both rural and urban areas under Current Weekly Status (CWS). Under CWS, a person's activity is assessed with reference to the preceding seven days. The bulletin says that quarterly rural estimates were first included in the April-June 2025 series; it also estimates an average 57.9 crore workers aged 15 and above in July-September 2026.$$,
$$Press Note on Periodic Labour Force Survey (PLFS) Quarterly Bulletin July-September 2026$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2334642&lang=1&reg=3$$,
$$National Statistical Office, Ministry of Statistics & Programme Implementation / Press Information Bureau$$, $$2026-11-10$$,
$$["PLFS is conducted by the National Statistical Office under MoSPI.","For persons aged 15 and above, overall LFPR was 55.5% and WPR was 52.7% in July-September 2026.","Rural unemployment rate under CWS was 4.3%, down from 4.8% in the preceding quarter.","Current Weekly Status uses the preceding seven days as the reference period."]$$::jsonb,
$$[{"question":"Which PLFS indicator measures the share of people who are working or seeking work?","answer":"Labour Force Participation Rate (LFPR). WPR instead measures the share who are working."}]$$::jsonb,
$${"title":"Reading a PLFS quarterly release","steps":["NSO collects labour-force information from households.","CWS classifies activity using the preceding week.","LFPR measures participation; WPR measures employment; UR measures joblessness among the labour force.","Quarterly estimates show rural and urban labour-market patterns."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-11-pli-medical-devices-extension$$, $$2026-11-11$$,
$$PLI scheme for medical devices is extended to 2035-36$$,
$$The Department of Pharmaceuticals invited fresh applications under the Production Linked Incentive Scheme for medical devices, extending the scheme to 2035-36. The release says about Rs 2,700 crore remains available and removes the minimum sales threshold for claiming an incentive while reducing the minimum-investment requirement.$$,
$$This connects industrial policy, healthcare manufacturing and import substitution. It is useful for distinguishing a PLI incentive from a procurement programme, and for identifying how policy can target components as well as finished devices.$$,
$$Launched in 2021-22, PLI-MD supports domestic production of medical devices. The revised scheme has four target segments: consumables, disposables and implants; critical components; high-end devices at a nascent domestic-manufacturing stage; and high-end devices that are currently assembled in India. The release says the application window will remain continuously open over a long period.$$,
$$Fresh applications invited under PLI Scheme for Medical Devices$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2334770&lang=1&reg=3$$,
$$Department of Pharmaceuticals, Ministry of Chemicals and Fertilizers / Press Information Bureau$$, $$2026-11-10$$,
$$["PLI-MD has been extended to 2035-36.","The release cites approximately Rs 2,700 crore of available scheme outlay.","It identifies four target segments, including critical components and high-end medical devices.","The revised scheme discontinues the minimum sales threshold for an incentive claim and trims the minimum investment requirement."]$$::jsonb,
$$[{"question":"Does PLI-MD only cover finished medical devices?","answer":"No. Its target segments also include critical components, alongside consumables, implants and specified high-end devices."}]$$::jsonb,
$${"title":"PLI-MD 2.0 and domestic manufacturing","steps":["The Department of Pharmaceuticals opens applications under PLI-MD.","Applicants propose manufacturing in one or more target segments.","Production-linked incentives support domestic value-chain development.","The scheme aims to deepen manufacturing capability in medical technology."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-11-coal-lignite-gasification-round-three$$, $$2026-11-11$$,
$$Third application round opens under the coal and lignite gasification scheme$$,
$$The Ministry of Coal opened the third round of its Rs 37,500 crore Scheme for Promotion of Surface Coal/Lignite Gasification Projects. The second round closed with two NTPC applications: one for urea and another for methanol and dimethyl ether. The ministry set 11 January 2027 as the third-round application deadline.$$,
$$This is an energy-security and industrial-policy update. It links coal gasification with feedstocks such as urea, methanol and DME, while making clear that an application round is not the same as a project approval or commercial production.$$,
$$Coal gasification converts coal into synthesis gas that can be used to make fuels and chemicals. The Cabinet approved this surface coal/lignite gasification scheme on 13 May 2026. The release places it within the national aim of reaching 100 million tonnes of coal-gasification capacity by 2030.$$,
$$Round 2 of Rs 37,500 Crore Scheme for Promotion of Surface Coal/Lignite Gasification Projects Concludes with Two Applications from NTPC Limited; Round 3 Opens Today$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2334671&lang=1&reg=3$$,
$$Ministry of Coal / Press Information Bureau$$, $$2026-11-10$$,
$$["The scheme has a Rs 37,500 crore financial outlay.","Round 3 opened on 10 November 2026 and applications are due by 11 January 2027.","NTPC's two round-two applications propose urea and methanol plus dimethyl ether.","Coal gasification produces synthesis gas for downstream fuels and chemicals."]$$::jsonb,
$$[{"question":"What should not be inferred from NTPC's round-two applications?","answer":"They are applications, not confirmation that the proposed gasification projects have been selected or are operating."}]$$::jsonb,
$${"title":"From coal to chemical products","steps":["A scheme invites proposals for surface coal or lignite gasification.","Gasification produces synthesis gas.","Syngas can be converted into products such as urea, methanol or DME.","Successive application rounds determine which proposals enter the selection process."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-11-yamuna-recreational-cruise-service$$, $$2026-11-11$$,
$$Delhi launches a recreational cruise service on the Yamuna$$,
$$A 30-seat electric recreational cruise service began on the Sonia Vihar-Jagatpur stretch of the Yamuna in Delhi. The official release describes an approximately six-kilometre round trip and says the project was developed by the Inland Waterways Authority of India with Delhi agencies.$$,
$$The launch is relevant to inland-waterway institutions, sustainable tourism and electric mobility. It also provides a useful example of a Union authority working with State and city bodies on a local waterway project.$$,
$$The Inland Waterways Authority of India is the statutory authority under the Ministry of Ports, Shipping and Waterways for the development and regulation of inland waterways. For this service, the release names the Delhi Development Authority, Delhi Tourism and Transportation Development Corporation, Delhi Jal Board and Delhi's Irrigation and Flood Control Department as partners.$$,
$$Delhi's River Tourism Begins with the Launch of Yamuna Recreational Cruise Service$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2334740&lang=1&reg=3$$,
$$Ministry of Ports, Shipping and Waterways / Press Information Bureau$$, $$2026-11-10$$,
$$["The service uses a 30-seat electric vessel on the Yamuna.","It operates on the Sonia Vihar-Jagatpur stretch in Delhi.","The reported round trip is about six kilometres.","IWAI developed the project with Delhi development, tourism, water and irrigation agencies."]$$::jsonb,
$$[{"question":"Which Union body developed the Yamuna recreational cruise project?","answer":"The Inland Waterways Authority of India (IWAI), working with Delhi agencies."}]$$::jsonb,
$${"title":"A city waterway tourism project","steps":["IWAI coordinates the inland-waterway project.","Delhi agencies contribute land, tourism, water and local-infrastructure functions.","An electric vessel provides the visitor service.","The project combines local recreation with a clean-mobility demonstration."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-11-new-aiims-opd-utilisation$$, $$2026-11-11$$,
$$New AIIMS record over six crore OPD consultations under PMSSY$$,
$$The new AIIMS established under the Pradhan Mantri Swasthya Suraksha Yojana collectively recorded more than six crore outpatient consultations from 2021-22 to 31 October 2026. Of 22 new AIIMS approved in different phases, the Health Ministry says 18 are fully functional.$$,
$$This is a health-infrastructure and public-service-delivery data point. It connects PMSSY with the expansion of tertiary care, medical education and research, rather than treating AIIMS solely as a single Delhi institution.$$,
$$PMSSY is a Union initiative to correct regional imbalances in access to affordable, reliable tertiary healthcare and to strengthen medical education. The release reports that annual OPD consultations at the new AIIMS rose from 50.03 lakh in 2021-22 to 144.96 lakh in 2025-26; 97.41 lakh consultations were recorded in 2026-27 up to October.$$,
$$New AIIMS cross 6 crore OPD consultations since 2021-22, expanding access to specialised tertiary healthcare across India$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2334756&lang=1&reg=3$$,
$$Ministry of Health and Family Welfare / Press Information Bureau$$, $$2026-11-10$$,
$$["The new AIIMS are being expanded under PMSSY.","22 new AIIMS have been approved in various phases; the release says 18 are fully functional.","Their cumulative OPD consultations exceeded six crore as of 31 October 2026.","PMSSY links tertiary healthcare expansion with medical education and research."]$$::jsonb,
$$[{"question":"What is PMSSY intended to address besides tertiary healthcare access?","answer":"Regional imbalances in healthcare and the strengthening of medical education and research."}]$$::jsonb,
$${"title":"PMSSY to patient access","steps":["PMSSY supports new institutions in underserved regions.","New AIIMS add tertiary-care, education and research capacity.","OPD consultations measure use of outpatient services.","Higher utilisation signals broader access, not a new legal entitlement by itself."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-11-bric-uk-cpi-biomanufacturing-loi$$, $$2026-11-11$$,
$$BRIC and the UK's Centre for Process Innovation sign a biomanufacturing letter of intent$$,
$$The Biotechnology Research and Innovation Council and the UK's Centre for Process Innovation signed a Letter of Intent to strengthen India-UK collaboration in biomanufacturing and support biofoundries. The announcement was made at BRIC's third Foundation Day at the National Institute of Immunology.$$,
$$The item adds a concrete science-cooperation development to questions on biotechnology institutions, international S&T partnerships and the role of biofoundries. A Letter of Intent signals intended cooperation; it should not be described as a completed funding programme or treaty.$$,
$$BRIC is a Department of Biotechnology umbrella body for a network of research institutions. A biofoundry combines automated biological design, construction and testing to develop biological products and processes. The release identifies biofoundry hubs at Mohali, Hyderabad, Pune and Thiruvananthapuram.$$,
$$BRIC's third Foundation Day celebrated at NII$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2334716&lang=1&reg=3$$,
$$Biotechnology Research and Innovation Council / Ministry of Science & Technology / Press Information Bureau$$, $$2026-11-10$$,
$$["BRIC signed the Letter of Intent with the UK's Centre for Process Innovation.","The stated focus is India-UK biomanufacturing collaboration and support for biofoundries.","BRIC is linked to the Department of Biotechnology's research-institution network.","A Letter of Intent expresses planned cooperation and is not itself proof of a funded project outcome."]$$::jsonb,
$$[{"question":"What is the appropriate way to describe the BRIC-CPI instrument?","answer":"A Letter of Intent for cooperation, not a completed bilateral treaty or a project already funded by the release."}]$$::jsonb,
$${"title":"Biomanufacturing cooperation","steps":["BRIC connects Indian biotechnology research institutions.","A Letter of Intent links BRIC with the UK's Centre for Process Innovation.","The cooperation targets biomanufacturing and biofoundry capability.","Research infrastructure can support scale-up from laboratory processes to industrial applications."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-11-india-hundredth-chess-grandmaster$$, $$2026-11-11$$,
$$Anuj Shrivatri becomes India's 100th chess Grandmaster$$,
$$Anuj Shrivatri became India's 100th chess Grandmaster, marking a national milestone in the sport. The Prime Minister's Office confirmed the achievement; ChessBase India reported that he secured the title after winning the seventh ASEAN Plus Individual Open Championship.$$,
$$The milestone is useful for sports current affairs and for factual questions on India's chess ecosystem. It should be kept distinct from an Olympic or government award: Grandmaster is a chess title administered internationally through the FIDE system.$$,
$$Grandmaster is the highest regular title in over-the-board chess. The title is generally associated with performance and rating requirements administered by the International Chess Federation (FIDE). Shrivatri is from Madhya Pradesh; contemporary tournament coverage identifies him as the State's first Grandmaster.$$,
$$Prime Minister congratulates Anuj Shrivatri on becoming India's 100th Chess Grandmaster$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2334594&lang=1&reg=3$$,
$$Prime Minister's Office / Press Information Bureau$$, $$2026-11-10$$,
$$["Anuj Shrivatri is India's 100th chess Grandmaster.","The Grandmaster title belongs to the international chess system administered by FIDE.","The official PMO release records the national milestone on 10 November 2026.","The achievement is a sporting milestone, not a government service rank or civilian award."]$$::jsonb,
$$[{"question":"Which body administers the Grandmaster title in international chess?","answer":"FIDE, the International Chess Federation."}]$$::jsonb,
$${"title":"A chess-title milestone","steps":["Players compete in rated international events.","FIDE's title system recognises prescribed achievement standards.","Anuj Shrivatri secured the Grandmaster title.","India's total reached one hundred Grandmasters."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-11-dgtr-aluminium-extrusions-anti-dumping-investigation$$, $$2026-11-11$$,
$$DGTR begins a suo-motu anti-dumping investigation into aluminium extrusions$$,
$$The Directorate General of Trade Remedies initiated a suo-motu anti-dumping investigation concerning aluminium extrusion profiles, structures and related articles imported from China PR, Malaysia, Vietnam and Thailand. The regulator lists the matter as SETU case AD/OI/079/2026.$$,
$$This is a trade-remedy development that tests the difference between opening an investigation and imposing an anti-dumping duty. It also highlights DGTR's role in investigating alleged injury to domestic industry under India's trade-remedy framework.$$,
$$Dumping concerns exports sold below a normal value in a way that may injure domestic industry. DGTR investigates and may recommend a remedy; any eventual customs duty follows the applicable legal process and is not created merely by an initiation notification. SETU is DGTR's unified filing and document-management portal for trade-remedy proceedings.$$,
$$Suo-Moto anti-dumping investigation concerning imports of Aluminium Extrusion Profiles, Structures and Articles thereof from China PR, Malaysia, Vietnam and Thailand$$,
$$https://www.dgtr.gov.in/en/anti-dumping-cases/suo-moto-anti-dumping-investigation-concerning-imports-aluminium-extrusion$$,
$$Directorate General of Trade Remedies, Department of Commerce$$, $$2026-11-09$$,
$$["DGTR opened a suo-motu anti-dumping investigation into specified aluminium extrusions and related articles.","The listed countries are China PR, Malaysia, Vietnam and Thailand.","The case identifier is AD/OI/079/2026.","Initiation starts an investigation; it does not by itself impose an anti-dumping duty."]$$::jsonb,
$$[{"question":"Does a DGTR initiation notification itself levy anti-dumping duty?","answer":"No. It opens the investigation; any duty requires the subsequent legal and notification process."}]$$::jsonb,
$${"title":"How an anti-dumping matter proceeds","steps":["DGTR initiates an investigation into alleged dumping and injury.","Importers, exporters and domestic producers can participate in the proceeding.","DGTR analyses evidence and issues findings or recommendations.","A duty, if warranted, requires the later statutory customs process."]}$$::jsonb, $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = now(),
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
$$2026-11-11-plfs-july-september-quarterly-bulletin$$,
$$2026-11-11-pli-medical-devices-extension$$,
$$2026-11-11-coal-lignite-gasification-round-three$$,
$$2026-11-11-yamuna-recreational-cruise-service$$,
$$2026-11-11-new-aiims-opd-utilisation$$,
$$2026-11-11-bric-uk-cpi-biomanufacturing-loi$$,
$$2026-11-11-india-hundredth-chess-grandmaster$$,
$$2026-11-11-dgtr-aluminium-extrusions-anti-dumping-investigation$$
)
and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict (brief_id, exam_id) do nothing;
